size_t ap_m68040_iu_group_count(void) {
  return sizeof groups / sizeof groups[0];
}

const ap_m68040_iu_group_t *ap_m68040_iu_group(size_t index) {
  return (index < ap_m68040_iu_group_count()) ? &groups[index] : NULL;
}

const ap_m68040_iu_group_t *ap_m68040_iu_find(const char *instruction) {
  for (size_t g = 0; g < ap_m68040_iu_group_count(); g++) {
    for (const char *const *n = groups[g].instructions; *n != NULL; n++) {
      if (strcmp(*n, instruction) == 0) {
        return &groups[g];
      }
    }
  }
  return NULL;
}

ap_m68040_iu_cell_t ap_m68040_iu_timing(const char *instruction,
                                        ap_m68040_iu_mode_t mode) {
  const ap_m68040_iu_group_t *group = ap_m68040_iu_find(instruction);
  if (group == NULL || mode >= AP_M68040_IU_MODE_COUNT) {
    return (ap_m68040_iu_cell_t){0};
  }
  return group->cells[mode];
}

static unsigned penalty_for(ap_m68040_iu_cell_t cell,
                            const ap_m68040_iu_condition_t *conditions,
                            size_t condition_count, bool execute_stage) {
  unsigned total = 0;
  for (unsigned p = 0; p < AP_M68040_IU_MAX_PENALTIES; p++) {
    const ap_m68040_iu_penalty_t *penalty = &cell.penalty[p];
    if (penalty->condition == AP_M68040_IU_CONDITION_NONE) {
      continue;
    }
    for (size_t i = 0; i < condition_count; i++) {
      if (conditions[i] != penalty->condition) {
        continue;
      }
      total += execute_stage ? penalty->execute : penalty->calculate;
      break;
    }
  }
  return total;
}

unsigned ap_m68040_iu_calculate(ap_m68040_iu_cell_t cell, bool alternate,
                                const ap_m68040_iu_condition_t *conditions,
                                size_t condition_count) {
  const unsigned base =
      (cell.alternate != AP_M68040_IU_ALTERNATE_NONE && alternate)
          ? cell.alternate_calculate
          : cell.calculate;
  return base + penalty_for(cell, conditions, condition_count, false);
}

ap_m68040_execute_t ap_m68040_iu_execute(
    ap_m68040_iu_cell_t cell, bool alternate,
    const ap_m68040_iu_condition_t *conditions, size_t condition_count) {
  ap_m68040_execute_t e =
      (cell.alternate != AP_M68040_IU_ALTERNATE_NONE && alternate)
          ? cell.alternate_execute
          : cell.execute;
  e.base += penalty_for(cell, conditions, condition_count, true);
  return e;
}

unsigned ap_m68040_iu_zero_divide_clocks(const ap_m68040_iu_group_t *group,
                                         ap_m68040_iu_mode_t mode) {
  if (group == NULL || !group->traps_on_zero_divide ||
      mode >= AP_M68040_IU_MODE_COUNT || !group->cells[mode].valid) {
    return 0u;
  }
  /* The `<ea>` calculate of the *normal* figure: the address still has to be
   * formed before the divisor can be found to be zero. */
  return AP_M68040_IU_ZERO_DIVIDE_BASE + group->cells[mode].calculate;
}
